{
  "claims": [
    {
      "claim_text": "Because transaction IDs are only 32 bits wide, the XID space holds about 4 billion values, and every normal XID has roughly two billion older and two billion newer XIDs.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that transaction IDs are 32 bits (allowing for more than 4 billion transactions) and that for every normal XID, there are two billion older and two billion newer XIDs.",
      "citations": [
        {
          "index": 0,
          "quote": "transaction IDs have limited size (32 bits)"
        },
        {
          "index": 0,
          "quote": "more than 4 billion transactions"
        },
        {
          "index": 1,
          "quote": "for every normal XID, there are two billion XIDs that are “older” and two billion that are “newer”"
        }
      ]
    },
    {
      "claim_text": "every table must be vacuumed at least once every two billion transactions",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that it is necessary to vacuum every table at least once every two billion transactions to avoid transaction ID wraparound.",
      "citations": [
        {
          "index": 0,
          "quote": "it is necessary to vacuum every table in every database at least once every two billion transactions."
        }
      ]
    },
    {
      "claim_text": "running past that without vacuuming means permanent, unrecoverable data loss.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage clarifies that while it results in catastrophic data loss where data becomes invisible, the data is actually still there and not permanently unrecoverable.",
      "citations": [
        {
          "index": 0,
          "quote": "Actually the data is still there, but that's cold comfort if you cannot get at it."
        }
      ]
    },
    {
      "claim_text": "With the default autovacuum_freeze_max_age of 200 million transactions, the anti-wraparound autovacuum kicks in after only about 10% of that two-billion window.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states the default for autovacuum_freeze_max_age is 200 million transactions, which is 10% of the two billion transaction window.",
      "citations": [
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        }
      ]
    },
    {
      "claim_text": "The effective maximum for vacuum_freeze_table_age is 95% of autovacuum_freeze_max_age, so with the default it can be at most 180 million.",
      "verdict": "CONTRADICTED",
      "reasoning": "While the passage states the maximum is 0.95 * autovacuum_freeze_max_age, 95% of the default 200 million is 190 million, not 180 million.",
      "citations": [
        {
          "index": 4,
          "quote": "The effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age"
        },
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        }
      ]
    },
    {
      "claim_text": "If autovacuum still fails, warnings start when the oldest XIDs are forty million transactions from wraparound",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that warning messages are emitted when the oldest XIDs reach forty million transactions from the wraparound point.",
      "citations": [
        {
          "index": 6,
          "quote": "the system will begin to emit warning messages like this when the database's oldest XIDs reach forty million transactions from the wraparound point"
        }
      ]
    },
    {
      "claim_text": "and new XIDs are refused once fewer than three million remain,",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states the system will refuse to assign new XIDs once there are fewer than three million transactions left until wraparound.",
      "citations": [
        {
          "index": 7,
          "quote": "the system will refuse to assign new XIDs once there are fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_text": "leaving a 37-million-transaction window between the first warning and the hard stop.",
      "verdict": "SUPPORTED",
      "reasoning": "The difference between the 40 million transaction warning threshold and the 3 million transaction hard stop is 37 million transactions.",
      "citations": [
        {
          "index": 6,
          "quote": "forty million transactions from the wraparound point"
        },
        {
          "index": 7,
          "quote": "fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_text": "Once XID assignment stops, no new transactions of any kind can be started.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states that while new XIDs are refused, read-only transactions can still be started.",
      "citations": [
        {
          "index": 8,
          "quote": "only read-only transactions can be started."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "Autovacuum relies on the statistics collection facility, so if track_counts is off, autovacuum cannot be used.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that autovacuum uses the statistics collection facility and cannot be used unless track_counts is true.",
      "citations": [
        {
          "index": 1,
          "quote": "These checks use the statistics collection facility; therefore, autovacuum cannot be used unless track_counts is set to true."
        }
      ]
    },
    {
      "claim_text": "Turning track_counts on is by itself enough for autovacuum to work.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage states that track_counts must be true for autovacuum to be used (a necessary condition), but it does not state that this alone is sufficient for autovacuum to work.",
      "citations": []
    },
    {
      "claim_text": "Even when autovacuum is disabled, PostgreSQL still invokes it on tables that might contain unfrozen rows with XIDs older than autovacuum_freeze_max_age.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that autovacuum is invoked for such tables even if autovacuum is disabled.",
      "citations": [
        {
          "index": 0,
          "quote": "autovacuum is invoked on any table that might contain unfrozen rows with XIDs older than the age specified by the configuration parameter autovacuum_freeze_max_age. (This will happen even if autovacuum is disabled.)"
        }
      ]
    },
    {
      "claim_text": "The launcher tries to start one worker per database every autovacuum_naptime seconds.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states the launcher attempts to start one worker within each database every autovacuum_naptime seconds.",
      "citations": [
        {
          "index": 2,
          "quote": "The launcher will distribute the work across time, attempting to start one worker within each database every autovacuum_naptime seconds."
        }
      ]
    },
    {
      "claim_text": "With 4 databases and autovacuum_naptime set to 60 seconds, a new worker starts about every 15 seconds.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage provides the formula autovacuum_naptime/N seconds for N databases. 60 / 4 = 15 seconds.",
      "citations": [
        {
          "index": 2,
          "quote": "Therefore, if the installation has N databases, a new worker will be launched every autovacuum_naptime/N seconds."
        }
      ]
    },
    {
      "claim_text": "Each database gets at most one worker at a time.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states there is no limit on how many workers might be in a single database.",
      "citations": [
        {
          "index": 3,
          "quote": "There is no limit on how many workers might be in a single database"
        }
      ]
    },
    {
      "claim_text": "Running workers count against max_connections.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states that the number of running workers does not count towards max_connections limits.",
      "citations": [
        {
          "index": 3,
          "quote": "Note that the number of running workers does not count towards max_connections or superuser_reserved_connections limits."
        }
      ]
    },
    {
      "claim_text": "Autovacuum processes partitions like ordinary tables.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that autovacuum processes table partitions just like other tables.",
      "citations": [
        {
          "index": 5,
          "quote": "Autovacuum does process table partitions just like other tables."
        }
      ]
    },
    {
      "claim_text": "Autovacuum does not run ANALYZE on partitioned tables.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that autovacuum does not run ANALYZE on partitioned tables.",
      "citations": [
        {
          "index": 5,
          "quote": "autovacuum does not run ANALYZE on partitioned tables"
        }
      ]
    },
    {
      "claim_text": "Autovacuum does not issue ANALYZE for foreign tables.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that the autovacuum daemon does not issue ANALYZE commands for foreign tables.",
      "citations": [
        {
          "index": 7,
          "quote": "The autovacuum daemon does not issue ANALYZE commands for foreign tables"
        }
      ]
    },
    {
      "claim_text": "Normally a conflicting lock request interrupts autovacuum.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explains that lock acquisition will interrupt autovacuum if it conflicts with the SHARE UPDATE EXCLUSIVE lock.",
      "citations": [
        {
          "index": 6,
          "quote": "If a process attempts to acquire a lock that conflicts with the SHARE UPDATE EXCLUSIVE lock held by autovacuum, lock acquisition will interrupt the autovacuum."
        }
      ]
    },
    {
      "claim_text": "A conflicting lock request also interrupts an autovacuum that is running to prevent transaction ID wraparound.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states that if autovacuum is running to prevent transaction ID wraparound, it is not automatically interrupted.",
      "citations": [
        {
          "index": 6,
          "quote": "However, if the autovacuum is running to prevent transaction ID wraparound (i.e., the autovacuum query name in the pg_stat_activity view ends with (to prevent wraparound)), the autovacuum is not automatically interrupted."
        }
      ]
    }
  ]
}

{
  "claims": [
