      "citations": [
        {
          "index": 2,
          "quote": "However, it will not return the space to the operating system, except in the special case where one or more pages at the end of a table become entirely free and an exclusive table lock can be easily obtained."
        }
      ]
    },
    {
      "claim_text": "VACUUM FULL, CLUSTER and the table-rewriting forms of ALTER TABLE all temporarily need extra disk space roughly equal to the size of the table.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that these commands temporarily use extra disk space approximately equal to the size of the table.",
      "citations": [
        {
          "index": 6,
          "quote": "you will need to use VACUUM FULL, or alternatively CLUSTER or one of the table-rewriting variants of ALTER TABLE."
        },
        {
          "index": 6,
          "quote": "Note that they also temporarily use extra disk space approximately equal to the size of the table"
        }
      ]
    },
    {
      "claim_text": "Rewriting a 50 GB table needs about another 50 GB free.",
      "verdict": "SUPPORTED",
      "reasoning": "This is a direct application of the rule stated in the passage that rewriting a table requires extra disk space approximately equal to the size of the table.",
      "citations": [
        {
          "index": 6,
          "quote": "Note that they also temporarily use extra disk space approximately equal to the size of the table"
        }
      ]
    },
    {
      "claim_text": "The autovacuum daemon never issues VACUUM FULL.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that the autovacuum daemon will never issue VACUUM FULL.",
      "citations": [
        {
          "index": 3,
          "quote": "The autovacuum daemon attempts to work this way, and in fact will never issue VACUUM FULL."
        }
      ]
    },
    {
      "claim_text": "A VACUUM FULL that shows up in your logs was not started by autovacuum.",
      "verdict": "SUPPORTED",
      "reasoning": "Since the autovacuum daemon never issues VACUUM FULL, any VACUUM FULL command must have been started by something else.",
      "citations": [
        {
          "index": 3,
          "quote": "The autovacuum daemon attempts to work this way, and in fact will never issue VACUUM FULL."
        }
      ]
    },
    {
      "claim_text": "For a table whose entire contents are deleted periodically, TRUNCATE avoids the need for a follow-up VACUUM, at the cost of violating strict MVCC semantics.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that TRUNCATE removes the entire content immediately without requiring a subsequent VACUUM, but the disadvantage is that strict MVCC semantics are violated.",
      "citations": [
        {
          "index": 7,
          "quote": "If you have a table whose entire contents are deleted on a periodic basis, consider doing it with TRUNCATE rather than using DELETE followed by VACUUM. TRUNCATE removes the entire content of the table immediately, without requiring a subsequent VACUUM or VACUUM FULL to reclaim the now-unused disk space. The disadvantage is that strict MVCC semantics are violated."
        }
      ]
    },
    {
      "claim_text": "Installations with extremely high update rates may vacuum their busiest tables as often as every few minutes.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly mentions that some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes.",
      "citations": [
        {
          "index": 5,
          "quote": "(Some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes.)"
        }
      ]
    },
    {
      "claim_text": "Anyone not using autovacuum is required to run a database-wide VACUUM once a day.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage states that running a database-wide VACUUM once a day is a 'typical approach' for those not using autovacuum, but it does not state that it is strictly required.",
      "citations": []
    }
  ]
}

