{
  "claims": [
    {
      "claim_text": "Because the wal-index lives in shared memory, all processes using a WAL database must be on the same host, so two processes on different machines sharing a database over NFS cannot use WAL.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that WAL requires processes to share memory (the wal-index), meaning all processes must be on the same host and it will not work over a network filesystem.",
      "citations": [
        {
          "index": 0,
          "quote": "All processes using a database must be on the same host computer; WAL does not work over a network filesystem. This is because WAL requires all processes to share a small amount of memory"
        },
        {
          "index": 1,
          "quote": "the use of shared memory means that all readers must exist on the same machine. This is why the write-ahead log implementation will not work on a network filesystem."
        }
      ]
    },
    {
      "claim_text": "Being on the same host, however, is enough to guarantee that WAL will work.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passages indicate that being on the same host is not sufficient to guarantee WAL will work; if the VFS does not support shared-memory methods and NORMAL locking mode is used, opening or converting to WAL mode will fail.",
      "citations": [
        {
          "index": 5,
          "quote": "If the VFS does not support shared-memory methods, then the attempt to open a database that is already in WAL mode, or the attempt to convert a database into WAL mode, will fail."
        }
      ]
    },
    {
      "claim_text": "Since there is only one WAL file, two writers can never be writing at the same moment, even though readers can run alongside a writer;",
      "verdict": "SUPPORTED",
      "reasoning": "The passages explicitly state that there can only be one writer at a time because there is only one WAL file, but writers and readers can run at the same time.",
      "citations": [
        {
          "index": 2,
          "quote": "However, since there is only one WAL file, there can only be one writer at a time."
        },
        {
          "index": 2,
          "quote": "writers and readers can run at the same time."
        }
      ]
    },
    {
      "claim_text": "this single-writer limit can be lifted with BEGIN CONCURRENT.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The provided passages do not mention 'BEGIN CONCURRENT' or any mechanism to lift the single-writer limit.",
      "citations": []
    },
    {
      "claim_text": "A process can use WAL without shared memory only if it sets EXCLUSIVE locking mode before its first WAL access, and in that case it stays in EXCLUSIVE mode until it leaves WAL journal mode.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages confirm that WAL can be used without shared memory if EXCLUSIVE locking mode is set before the first access, and that the only way to change out of this mode is to change out of WAL journal mode.",
      "citations": [
        {
          "index": 3,
          "quote": "WAL databases can be created, read, and written even if shared memory is unavailable as long as the locking_mode is set to EXCLUSIVE before the first attempted access."
        },
        {
          "index": 4,
          "quote": "The only way to change out of EXCLUSIVE locking mode is to first change out of WAL journal mode."
        }
      ]
    },
    {
      "claim_text": "With PRAGMA synchronous=NORMAL, commits skip the WAL sync and the checkpoint is the only operation that issues a sync;",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that with PRAGMA synchronous set to NORMAL, the sync on commit is omitted and the checkpoint is the only operation to issue a sync.",
      "citations": [
        {
          "index": 6,
          "quote": "omit this sync if PRAGMA synchronous is set to NORMAL."
        },
        {
          "index": 7,
          "quote": "Note that with PRAGMA synchronous set to NORMAL, the checkpoint is the only operation to issue an I/O barrier or sync operation"
        }
      ]
    },
    {
      "claim_text": "with FULL, every commit syncs the WAL.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL.",
      "citations": [
        {
          "index": 6,
          "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL"
        }
      ]
    },
    {
      "claim_text": "Running the checkpoint in a separate thread therefore guarantees that the main thread never blocks on a sync, whatever the synchronous setting.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passages specify that running the checkpoint in a separate thread prevents the main thread from blocking on a sync specifically when PRAGMA synchronous is set to NORMAL. If it is set to FULL, writers sync the WAL on every commit, meaning the main thread would still block on syncs during commits.",
      "citations": [
        {
          "index": 7,
          "quote": "Note that with PRAGMA synchronous set to NORMAL, the checkpoint is the only operation to issue an I/O barrier or sync operation... If an application therefore runs checkpoint in a separate thread or process, the main thread or process that is doing database queries and updates will never block on a sync operation."
        },
        {
          "index": 6,
          "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL"
        }
      ]
    }
  ]
}

